import React, { useMemo, useState } from "react";
import {
  Box,
  Button,
  Container,
  CssBaseline,
  Paper,
  Stack,
  TextField,
  ThemeProvider,
  Typography,
  createTheme,
} from "@mui/material";
import { styled } from "@mui/system";
import dayjs from "dayjs";
import duration from "dayjs/plugin/duration";
import gif1 from "./video/gif1.gif";
import gif2 from "./video/gif2.gif";
import gif3 from "./video/gif3.gif";

dayjs.extend(duration);

const theme = createTheme({
  palette: {
    mode: "light",
    primary: {
      main: "#4f7cff",
    },
    secondary: {
      main: "#5aa9c9",
    },
    background: {
      default: "#e7eef6",
      paper: "#f5f8fc",
    },
    text: {
      primary: "#223244",
      secondary: "#607286",
    },
  },
  shape: {
    borderRadius: 10,
  },
  typography: {
    fontFamily: '"Segoe UI", "Trebuchet MS", sans-serif',
    h4: {
      fontWeight: 800,
      letterSpacing: "-0.02em",
    },
    h6: {
      fontWeight: 700,
    },
    button: {
      textTransform: "none",
      fontWeight: 700,
    },
  },
});

const FormTextField = styled(TextField)({
  "& .MuiInputLabel-root": {
    color: "#64788c",
    fontWeight: 600,
  },
  "& .MuiInputLabel-root.Mui-focused": {
    color: "#4f7cff",
  },
  "& .MuiOutlinedInput-root": {
    borderRadius: 8,
    backgroundColor: "#fbfdff",
    color: "#223244",
    "& fieldset": {
      borderColor: "#cad8e6",
    },
    "&:hover fieldset": {
      borderColor: "#aebfd1",
    },
    "&.Mui-focused fieldset": {
      borderColor: "#4f7cff",
      borderWidth: 2,
    },
  },
});

const PrimaryButton = styled(Button)({
  borderRadius: 999,
  padding: "12px 18px",
  backgroundColor: "#4f7cff",
  boxShadow: "none",
  "&:hover": {
    backgroundColor: "#3f69e0",
    boxShadow: "none",
  },
});

const SecondaryButton = styled(Button)({
  borderRadius: 999,
  padding: "12px 18px",
  borderColor: "#c6d4e1",
  color: "#607286",
  "&:hover": {
    borderColor: "#afc1d3",
    backgroundColor: "#edf3f9",
  },
});

const moodConfig = {
  1: {
    chip: "Long way to go",
    text: "Abhi logout ka sapna thoda door hai.",
    gif: gif1,
  },
  2: {
    chip: "Almost there",
    text: "Bas thoda aur, phir azaadi hi azaadi.",
    gif: gif2,
  },
  3: {
    chip: "You are free",
    text: "Aaj ka kaam khatam, ab zindagi shuru.",
    gif: gif3,
  },
};

function App() {
  const [loginTime, setLoginTime] = useState("");
  const [requiredHours, setRequiredHours] = useState("07:45");
  const [effectiveHours, setEffectiveHours] = useState("");
  const [lastLoginTime, setLastLoginTime] = useState("");
  const [logoutTime, setLogoutTime] = useState("");
  const [remainingTime, setRemainingTime] = useState("");
  const [hasCalculated, setHasCalculated] = useState(false);
  const [gifStage, setGifStage] = useState(null);

  const mood = useMemo(() => {
    if (!gifStage) return null;
    return moodConfig[gifStage];
  }, [gifStage]);

  const calculateLogoutTime = () => {
    if (!loginTime || !requiredHours || !effectiveHours || !lastLoginTime) {
      alert("Please fill all the fields correctly.");
      return;
    }

    const [effH, effM] = effectiveHours.split(":").map(Number);
    const totalEffectiveMinutes = effH * 60 + effM;

    const [reqH, reqM] = requiredHours.split(":").map(Number);
    const requiredMinutes = reqH * 60 + reqM;

    const remainingMinutes = requiredMinutes - totalEffectiveMinutes;

    setHasCalculated(true);

    if (remainingMinutes <= 0) {
      setGifStage(3);
      setRemainingTime("0h 0m");
      setLogoutTime("You can log out now");
      return;
    }

    if (remainingMinutes > requiredMinutes / 2) {
      setGifStage(1);
    } else {
      setGifStage(2);
    }

    const [lastH, lastM] = lastLoginTime.split(":").map(Number);
    const lastLogin = dayjs().hour(lastH).minute(lastM);
    const logout = lastLogin.add(remainingMinutes, "minute");

    setRemainingTime(
      `${Math.floor(remainingMinutes / 60)}h ${remainingMinutes % 60}m`,
    );
    setLogoutTime(logout.format("hh:mm A"));
  };

  const clearFields = () => {
    setLoginTime("");
    setRequiredHours("07:45");
    setEffectiveHours("");
    setLastLoginTime("");
    setLogoutTime("");
    setRemainingTime("");
    setHasCalculated(false);
    setGifStage(null);
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box
        sx={{
          minHeight: "100vh",
          background:
            "linear-gradient(180deg, #eef4fa 0%, #e3ebf4 50%, #d9e4ef 100%)",
          py: { xs: 2, md: 3 },
          display: "flex",
          alignItems: "center",
        }}
      >
        <Container maxWidth="lg">
          <Stack
            spacing={{ xs: 2.5, md: 3 }}
            sx={{ alignItems: "center" }}
          >
            <Box
              sx={{
                width: "100%",
                maxWidth: hasCalculated ? "100%" : 620,
                mx: "auto",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <Typography
                variant="h4"
                align="center"
                sx={{ mb: 1, width: "100%", textAlign: "center" }}
              >
                Work Hours Tracker
              </Typography>
              <Typography
                align="center"
                color="text.secondary"
                sx={{
                  width: "100%",
                  maxWidth: hasCalculated ? 640 : 560,
                  textAlign: "center",
                  mx: "auto",
                  display: "block",
                }}
              >
                Fill in your work details and calculate the exact time you can
                finally log out.
              </Typography>
            </Box>

            <Box
              sx={{
                width: "100%",
                display: "grid",
                gridTemplateColumns: {
                  xs: "1fr",
                  md: hasCalculated ? "minmax(320px, 430px) minmax(360px, 1fr)" : "minmax(320px, 620px)",
                },
                justifyContent: "center",
                alignItems: "stretch",
                gap: { xs: 2, md: 2.5 },
              }}
            >
              <Paper
                elevation={0}
                sx={{
                  p: { xs: 2, sm: 2.4 },
                  borderRadius: 3,
                  backgroundColor: "background.paper",
                  border: "1px solid #d4e0eb",
                  boxShadow: "0 14px 26px rgba(61, 88, 118, 0.10)",
                  height: "100%",
                }}
              >
                <Stack spacing={1.6}>
                  <Typography variant="h6">Fill your details</Typography>

                  <FormTextField
                    label="Login Time"
                    type="time"
                    InputLabelProps={{ shrink: true }}
                    value={loginTime}
                    onChange={(e) => setLoginTime(e.target.value)}
                    fullWidth
                  />

                  <FormTextField
                    label="Required Hours (HH:mm)"
                    placeholder="e.g. 07:45"
                    value={requiredHours}
                    onChange={(e) => setRequiredHours(e.target.value)}
                    fullWidth
                  />

                  <FormTextField
                    label="Effective Hours Till Now (HH:mm)"
                    placeholder="e.g. 07:00"
                    value={effectiveHours}
                    onChange={(e) => setEffectiveHours(e.target.value)}
                    fullWidth
                  />

                  <FormTextField
                    label="Last Login Time"
                    type="time"
                    InputLabelProps={{ shrink: true }}
                    value={lastLoginTime}
                    onChange={(e) => setLastLoginTime(e.target.value)}
                    fullWidth
                  />

                  <Box
                    sx={{
                      display: "grid",
                      gridTemplateColumns: { xs: "1fr", sm: "1fr 1fr" },
                      gap: 1.5,
                    }}
                  >
                    <PrimaryButton
                      variant="contained"
                      onClick={calculateLogoutTime}
                      fullWidth
                    >
                      Calculate Logout Time
                    </PrimaryButton>
                    <SecondaryButton
                      variant="outlined"
                      onClick={clearFields}
                      fullWidth
                    >
                      Clear
                    </SecondaryButton>
                  </Box>
                </Stack>
              </Paper>

              {hasCalculated && mood && (
                <Paper
                  elevation={0}
                  sx={{
                    p: { xs: 1.75, sm: 2.1 },
                    borderRadius: 3,
                    backgroundColor: "#eef4f9",
                    border: "1px solid #d4dee8",
                    boxShadow: "0 14px 26px rgba(61, 88, 118, 0.10)",
                    display: "flex",
                    flexDirection: "column",
                    gap: 1.4,
                    height: "100%",
                  }}
                >
                  <Box>
                    <Typography variant="h6" sx={{ mb: 0.4 }}>
                      Work Mood
                    </Typography>
                    <Typography color="text.secondary" sx={{ fontSize: "0.97rem" }}>
                      {mood.text}
                    </Typography>
                  </Box>

                  <Paper
                    elevation={0}
                    sx={{
                      p: 1.2,
                      borderRadius: 2,
                      backgroundColor: "#f7fbff",
                      border: "1px solid #cfdae5",
                    }}
                  >
                    <Typography
                      sx={{
                        fontSize: "0.98rem",
                        fontWeight: 700,
                        mb: 0.5,
                      }}
                    >
                      Remaining Time: {remainingTime}
                    </Typography>
                    <Typography sx={{ fontSize: "0.98rem" }}>
                      <strong>Logout Time:</strong> {logoutTime}
                    </Typography>
                  </Paper>

                  <Box
                    sx={{
                      borderRadius: 2,
                      overflow: "hidden",
                      backgroundColor: "#f4f9fd",
                      border: "1px solid #cfdae5",
                      minHeight: { xs: 180, md: 210 },
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      p: 1,
                    }}
                  >
                    <Box
                      component="img"
                      src={mood.gif}
                      alt="Work status gif"
                      sx={{
                        width: "100%",
                        maxWidth: 320,
                        height: { xs: 150, sm: 180, md: 180 },
                        objectFit: "contain",
                      }}
                    />
                  </Box>

                  <Typography
                    color="text.secondary"
                    sx={{ textAlign: "center", fontSize: "0.95rem" }}
                  >
                    {remainingTime === "0h 0m"
                      ? "All done. No extra minutes left."
                      : `${remainingTime} left before logout.`}
                  </Typography>
                </Paper>
              )}
            </Box>
          </Stack>
        </Container>
      </Box>
    </ThemeProvider>
  );
}

export default App;
